-- Carga determinística de 330 artículos de tejeduría para cruce con producción de Susana
ON CONFLICT (codigo) DO UPDATE SET
  etapa = 'TEJIDO',
  "codigoSusi" = COALESCE(articulos."codigoSusi", EXCLUDED."codigoSusi"),
  modelo = COALESCE(articulos.modelo, EXCLUDED.modelo),
  talle = COALESCE(articulos.talle, EXCLUDED.talle),
  variante = COALESCE(articulos.variante, EXCLUDED.variante),
  marca = COALESCE(articulos.marca, EXCLUDED.marca),
  estado = 'CHEQUEADO',
  activo = true;